begin;
\ir bag-reception-fixture.inc
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000000211','life-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000000212','life-reader@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000211","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Lifecycle test','lifecycle-test',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','seller@life.test','')::text,true);
select set_config('test.agreement',publish_seller_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),null,'Synthetic terms','Only a test','en',false)::text,true);
select record_agreement_evidence(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.agreement')::uuid,'Signed paper');
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy') || '{"vatModeConsignmentPrivate":"consignment_margin","vatModeStoreOwned":"store_full"}');
select set_config('test.bag',receive_bag_with_agreement(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'',current_setting('test.agreement')::uuid)::text,true);
select set_config('test.d1',gen_random_uuid()::text,true);
select pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.d1')::uuid,0,'Synthetic jacket','Jackets','Good');
select set_config('test.item',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'reception_review',current_setting('test.d1')::uuid,1,20000);
select set_config('test.end',gen_random_uuid()::text,true);
select set_config('test.observation',gen_random_uuid()::text,true);
select set_config('test.today',((now() at time zone 'Europe/Stockholm')::date)::text,true);
create function pg_temp.collect(p_id uuid,p_expected uuid,p_collected boolean default false,p_day date default current_setting('test.today')::date) returns uuid language sql as $$
 select public.record_item_collection(current_setting('test.tenant')::uuid,p_id,current_setting('test.item')::uuid,current_setting('test.end')::uuid,p_expected,p_collected,p_day,'Synthetic check');
$$;
select throws_like($$select pg_temp.collect(gen_random_uuid(),null)$$,'%ITEM_COLLECTION_UNAVAILABLE%','active stock cannot be marked collected');
select end_sale_period(current_setting('test.tenant')::uuid,current_setting('test.end')::uuid,current_setting('test.item')::uuid,'return');
select throws_like($$select pg_temp.collect(gen_random_uuid(),null,false,current_setting('test.today')::date+1)$$,'%INVALID_INPUT%','observation cannot be a future plan');
select throws_like($$select pg_temp.collect(gen_random_uuid(),null,null)$$,'%INVALID_INPUT%','status is required');
select throws_like($$select pg_temp.collect(gen_random_uuid(),null,false,'infinity')$$,'%INVALID_INPUT%','infinite date rejected');
select throws_like($$select pg_temp.collect(gen_random_uuid(),gen_random_uuid())$$,'%ITEM_COLLECTION_CHANGED%','stale expected observation refused');
select is(pg_temp.collect(current_setting('test.observation')::uuid,null),current_setting('test.observation')::uuid,'owner records not collected');
select is(pg_temp.collect(current_setting('test.observation')::uuid,null),current_setting('test.observation')::uuid,'exact replay returns existing observation');
select throws_like($$select pg_temp.collect(current_setting('test.observation')::uuid,null,true)$$,'%REQUEST_CONFLICT%','reusing request with another result refused');
select is((select count(*) from item_events where item_id=current_setting('test.item')::uuid and kind='collection_recorded'),1::bigint,'one event for replay');
select throws_like($$select pg_temp.collect(gen_random_uuid(),null,true)$$,'%ITEM_COLLECTION_CHANGED%','stale screen cannot overwrite saved evidence');
select is((select stage from lifecycle_queue(current_setting('test.tenant')::uuid) where item_id=current_setting('test.item')::uuid),'ended','collection does not reopen sale');
select is((select detail->>'endEventId' from item_events where id=current_setting('test.observation')::uuid),current_setting('test.end'),'evidence pins the return event');
select throws_ok($$insert into item_events(id,tenant_id,item_id,kind,actor) values(gen_random_uuid(),current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'collection_recorded',auth.uid())$$,'42501',null,'direct event writes stay denied');
reset role;
select throws_ok($$update item_events set detail='{}' where id=current_setting('test.observation')::uuid$$,'55000','IMMUTABLE_ITEM','saved evidence is immutable');
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000000212','readonly');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000212","role":"authenticated"}';
select throws_ok($$select pg_temp.collect(gen_random_uuid(),current_setting('test.observation')::uuid,true)$$,'42501','FORBIDDEN','readonly cannot record collection');
reset role;
update tenant_members set role='staff' where tenant_id=current_setting('test.tenant')::uuid and user_id='f0000000-0000-4000-8000-000000000212';
set local role authenticated;
select throws_like($$select pg_temp.collect(current_setting('test.observation')::uuid,null)$$,'%REQUEST_CONFLICT%','another actor cannot claim replay');
select set_config('test.second',gen_random_uuid()::text,true);
select is(pg_temp.collect(current_setting('test.second')::uuid,current_setting('test.observation')::uuid,true),current_setting('test.second')::uuid,'staff records later collection');
select is((select count(*) from item_events where item_id=current_setting('test.item')::uuid and kind='collection_recorded'),2::bigint,'correction appends a second event');
select ok((select occurred_at from item_events where id=current_setting('test.second')::uuid)>(select occurred_at from item_events where id=current_setting('test.observation')::uuid),'observations have stable order in one transaction');
select is((select detail->>'collected' from item_events where id=current_setting('test.observation')::uuid),'false','earlier check remains unchanged');
reset role;
update tenant_members set role='admin' where tenant_id=current_setting('test.tenant')::uuid and user_id='f0000000-0000-4000-8000-000000000212';
set local role authenticated;
select lives_ok($$select pg_temp.collect(gen_random_uuid(),current_setting('test.second')::uuid,false)$$,'admin can correct collection evidence');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000211","role":"authenticated"}';
select is(pg_temp.collect(current_setting('test.observation')::uuid,null),current_setting('test.observation')::uuid,'old exact replay succeeds after newer evidence without changing it');
select throws_ok($$select record_item_collection(gen_random_uuid(),gen_random_uuid(),current_setting('test.item')::uuid,current_setting('test.end')::uuid,null,false,current_setting('test.today')::date)$$,'42501','FORBIDDEN','tenant binding enforced before item lookup');
select set_config('test.d2',gen_random_uuid()::text,true);
select pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.d2')::uuid,0,'Synthetic charity jacket','Jackets','Good');
select set_config('test.item',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'reception_review',current_setting('test.d2')::uuid,1,20000);
select set_config('test.end',gen_random_uuid()::text,true);
select end_sale_period(current_setting('test.tenant')::uuid,current_setting('test.end')::uuid,current_setting('test.item')::uuid,'charity');
select throws_like($$select pg_temp.collect(gen_random_uuid(),null)$$,'%ITEM_COLLECTION_UNAVAILABLE%','charity is not a return-to-seller collection');
select * from finish();
rollback;
